CREATE TABLE IF NOT EXISTS "players" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account identity from the platform layer. Kept opaque so the matchmaker never needs the account service to answer a query.
	"external_id" VARCHAR(120) NOT NULL UNIQUE,
	-- Name shown in the lobby.
	"display_name" VARCHAR(40) NOT NULL,
	-- Region the player normally plays in, e.g. eu-west. A default for queue tickets, not a restriction.
	"home_region_code" VARCHAR(12) NOT NULL,
	-- pc | console | mobile. Drives crossplay eligibility, which is a filter on the queue rather than a separate queue.
	"platform" VARCHAR(16) NOT NULL DEFAULT 'pc',
	-- Account first seen by the matchmaker.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- End of the last match played. Inactivity beyond a threshold is what triggers rating decay.
	"last_match_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "players" IS 'A player the matchmaker can place. Nothing about progression or inventory lives here; this service only needs identity, region and platform.';
COMMENT ON COLUMN "players"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "players"."external_id" IS 'Account identity from the platform layer. Kept opaque so the matchmaker never needs the account service to answer a query.';
COMMENT ON COLUMN "players"."display_name" IS 'Name shown in the lobby.';
COMMENT ON COLUMN "players"."home_region_code" IS 'Region the player normally plays in, e.g. eu-west. A default for queue tickets, not a restriction.';
COMMENT ON COLUMN "players"."platform" IS 'pc | console | mobile. Drives crossplay eligibility, which is a filter on the queue rather than a separate queue.';
COMMENT ON COLUMN "players"."created_at" IS 'Account first seen by the matchmaker.';
COMMENT ON COLUMN "players"."last_match_at" IS 'End of the last match played. Inactivity beyond a threshold is what triggers rating decay.';

CREATE INDEX "idx_players_region"
ON "players" ("home_region_code");

CREATE TABLE IF NOT EXISTS "playlists" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable key, e.g. ranked_5v5. The client asks to queue by code.
	"code" VARCHAR(40) NOT NULL UNIQUE,
	-- Display name in the play menu.
	"name" VARCHAR(120) NOT NULL,
	-- Teams per match. Two for most modes, up to sixty for battle royale, which is why team count is data rather than an assumption.
	"team_count" SMALLINT NOT NULL DEFAULT 2,
	-- Slots per team. team_count multiplied by team_size is the roster the matchmaker must fill before proposing.
	"team_size" SMALLINT NOT NULL DEFAULT 5,
	-- Largest group allowed to queue together. Smaller than team_size in modes that deliberately break up premades.
	"max_party_size" SMALLINT NOT NULL DEFAULT 5,
	-- Ranked matches update skill_ratings; unranked ones still read ratings for balance but write no history.
	"is_ranked" BOOLEAN NOT NULL DEFAULT true,
	-- elo | glicko2 | trueskill. Named because the update formula and the meaning of sigma differ, and history rows must be interpreted under the system in force.
	"rating_system" VARCHAR(16) NOT NULL DEFAULT 'glicko2',
	-- Starting skill estimate for a new player in this playlist.
	"initial_mu" NUMERIC(8,3) NOT NULL DEFAULT 1500,
	-- Starting uncertainty. Large on purpose, so the first few results move the rating a long way.
	"initial_sigma" NUMERIC(8,3) NOT NULL DEFAULT 350,
	-- Closes the playlist without deleting its ratings and history.
	"is_enabled" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "playlists" IS 'One queueable mode. A queue is not a table here: it is the runtime pair of a playlist and a region, which is why tickets carry region_code and playlists do not.';
COMMENT ON COLUMN "playlists"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "playlists"."code" IS 'Stable key, e.g. ranked_5v5. The client asks to queue by code.';
COMMENT ON COLUMN "playlists"."name" IS 'Display name in the play menu.';
COMMENT ON COLUMN "playlists"."team_count" IS 'Teams per match. Two for most modes, up to sixty for battle royale, which is why team count is data rather than an assumption.';
COMMENT ON COLUMN "playlists"."team_size" IS 'Slots per team. team_count multiplied by team_size is the roster the matchmaker must fill before proposing.';
COMMENT ON COLUMN "playlists"."max_party_size" IS 'Largest group allowed to queue together. Smaller than team_size in modes that deliberately break up premades.';
COMMENT ON COLUMN "playlists"."is_ranked" IS 'Ranked matches update skill_ratings; unranked ones still read ratings for balance but write no history.';
COMMENT ON COLUMN "playlists"."rating_system" IS 'elo | glicko2 | trueskill. Named because the update formula and the meaning of sigma differ, and history rows must be interpreted under the system in force.';
COMMENT ON COLUMN "playlists"."initial_mu" IS 'Starting skill estimate for a new player in this playlist.';
COMMENT ON COLUMN "playlists"."initial_sigma" IS 'Starting uncertainty. Large on purpose, so the first few results move the rating a long way.';
COMMENT ON COLUMN "playlists"."is_enabled" IS 'Closes the playlist without deleting its ratings and history.';

CREATE TABLE IF NOT EXISTS "skill_ratings" (
	-- Player being rated. Half of the composite primary key.
	"player_id" BIGINT,
	-- Playlist the rating applies to. Half of the composite key, because skill at 5v5 says little about skill at 1v1.
	"playlist_id" BIGINT,
	-- Current skill estimate. On its own it is not a rank - it is the centre of a distribution.
	"mu" NUMERIC(8,3) NOT NULL,
	-- Uncertainty about mu. High sigma means the system is still guessing, and is what lets a new player be matched cautiously and moved quickly.
	"sigma" NUMERIC(8,3) NOT NULL,
	-- Glicko-2 measure of how erratic recent results have been. Raises the effective step size after a surprising streak.
	"volatility" NUMERIC(8,5) NOT NULL DEFAULT 0.06,
	-- Conservative number shown to the player, typically mu minus three sigma. Stored so the ladder can be sorted without recomputing it per row.
	"display_rating" INTEGER NOT NULL,
	-- Count in this playlist. Drives placement status and decay eligibility.
	"matches_played" INTEGER NOT NULL DEFAULT 0,
	-- True once placement matches are done. Unplaced players are hidden from the ladder but still matched.
	"is_placed" BOOLEAN NOT NULL DEFAULT false,
	-- When the rating last moved because of a result, as opposed to decay.
	"last_match_at" TIMESTAMPTZ,
	-- Last write of any kind.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("player_id", "playlist_id")
);

COMMENT ON TABLE "skill_ratings" IS 'The current rating, and only the current rating. It is a cache of the last row in rating_history, kept separately because the matchmaker reads it thousands of times a second and must never scan a history table to do so.';
COMMENT ON COLUMN "skill_ratings"."player_id" IS 'Player being rated. Half of the composite primary key.';
COMMENT ON COLUMN "skill_ratings"."playlist_id" IS 'Playlist the rating applies to. Half of the composite key, because skill at 5v5 says little about skill at 1v1.';
COMMENT ON COLUMN "skill_ratings"."mu" IS 'Current skill estimate. On its own it is not a rank - it is the centre of a distribution.';
COMMENT ON COLUMN "skill_ratings"."sigma" IS 'Uncertainty about mu. High sigma means the system is still guessing, and is what lets a new player be matched cautiously and moved quickly.';
COMMENT ON COLUMN "skill_ratings"."volatility" IS 'Glicko-2 measure of how erratic recent results have been. Raises the effective step size after a surprising streak.';
COMMENT ON COLUMN "skill_ratings"."display_rating" IS 'Conservative number shown to the player, typically mu minus three sigma. Stored so the ladder can be sorted without recomputing it per row.';
COMMENT ON COLUMN "skill_ratings"."matches_played" IS 'Count in this playlist. Drives placement status and decay eligibility.';
COMMENT ON COLUMN "skill_ratings"."is_placed" IS 'True once placement matches are done. Unplaced players are hidden from the ladder but still matched.';
COMMENT ON COLUMN "skill_ratings"."last_match_at" IS 'When the rating last moved because of a result, as opposed to decay.';
COMMENT ON COLUMN "skill_ratings"."updated_at" IS 'Last write of any kind.';

CREATE INDEX "idx_ratings_playlist_display"
ON "skill_ratings" ("playlist_id", "display_rating");

CREATE TABLE IF NOT EXISTS "rating_history" (
	-- Surrogate primary key, and the order in which changes were applied.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Player whose rating moved.
	"player_id" BIGINT NOT NULL,
	-- Playlist the change belongs to.
	"playlist_id" BIGINT NOT NULL,
	-- Match that caused it. Null for decay, placement seeding or a manual correction.
	"match_id" BIGINT,
	-- match_result | placement | decay | season_reset | manual. Without this a graph of a rating is uninterpretable.
	"reason" VARCHAR(24) NOT NULL DEFAULT 'match_result',
	-- Skill estimate before the update.
	"mu_before" NUMERIC(8,3) NOT NULL,
	-- Uncertainty before the update.
	"sigma_before" NUMERIC(8,3) NOT NULL,
	-- Skill estimate after. The pair of before and after makes each step auditable without replaying the whole chain.
	"mu_after" NUMERIC(8,3) NOT NULL,
	-- Uncertainty after. It usually shrinks with every result and grows again during inactivity.
	"sigma_after" NUMERIC(8,3) NOT NULL,
	-- Win probability the system predicted before the match. Comparing this against outcomes is the only honest way to measure whether the rating system works.
	"expected_score" NUMERIC(5,4),
	-- When the update was applied.
	"occurred_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "rating_history" IS 'Append-only log of every rating change. Storing only the current number makes a wrong update permanent and unprovable; with history a bad patch can be recomputed and a player can be shown why their rank moved.';
COMMENT ON COLUMN "rating_history"."id" IS 'Surrogate primary key, and the order in which changes were applied.';
COMMENT ON COLUMN "rating_history"."player_id" IS 'Player whose rating moved.';
COMMENT ON COLUMN "rating_history"."playlist_id" IS 'Playlist the change belongs to.';
COMMENT ON COLUMN "rating_history"."match_id" IS 'Match that caused it. Null for decay, placement seeding or a manual correction.';
COMMENT ON COLUMN "rating_history"."reason" IS 'match_result | placement | decay | season_reset | manual. Without this a graph of a rating is uninterpretable.';
COMMENT ON COLUMN "rating_history"."mu_before" IS 'Skill estimate before the update.';
COMMENT ON COLUMN "rating_history"."sigma_before" IS 'Uncertainty before the update.';
COMMENT ON COLUMN "rating_history"."mu_after" IS 'Skill estimate after. The pair of before and after makes each step auditable without replaying the whole chain.';
COMMENT ON COLUMN "rating_history"."sigma_after" IS 'Uncertainty after. It usually shrinks with every result and grows again during inactivity.';
COMMENT ON COLUMN "rating_history"."expected_score" IS 'Win probability the system predicted before the match. Comparing this against outcomes is the only honest way to measure whether the rating system works.';
COMMENT ON COLUMN "rating_history"."occurred_at" IS 'When the update was applied.';

CREATE INDEX "idx_rating_history_player_time"
ON "rating_history" ("player_id", "playlist_id", "occurred_at");
CREATE INDEX "idx_rating_history_match"
ON "rating_history" ("match_id");

CREATE TABLE IF NOT EXISTS "parties" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Who may start and cancel the search. Leadership moves rather than disbanding the party when the leader leaves.
	"leader_player_id" BIGINT NOT NULL,
	-- Playlist selected in the lobby. Null while the group is still deciding what to play.
	"playlist_id" BIGINT,
	-- Region the group will search in, usually the best shared ping rather than the leader home region.
	"region_code" VARCHAR(12) NOT NULL,
	-- forming | queued | in_match | disbanded. A party in_match cannot enqueue a second ticket.
	"state" VARCHAR(16) NOT NULL DEFAULT 'forming',
	-- Group formation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the group broke up. Rows are kept so a match roster can still explain who queued with whom.
	"disbanded_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "parties" IS 'A group that queues as a unit. Solo players get a party of one, which removes every branch in the matchmaker between solo and grouped entry.';
COMMENT ON COLUMN "parties"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "parties"."leader_player_id" IS 'Who may start and cancel the search. Leadership moves rather than disbanding the party when the leader leaves.';
COMMENT ON COLUMN "parties"."playlist_id" IS 'Playlist selected in the lobby. Null while the group is still deciding what to play.';
COMMENT ON COLUMN "parties"."region_code" IS 'Region the group will search in, usually the best shared ping rather than the leader home region.';
COMMENT ON COLUMN "parties"."state" IS 'forming | queued | in_match | disbanded. A party in_match cannot enqueue a second ticket.';
COMMENT ON COLUMN "parties"."created_at" IS 'Group formation time.';
COMMENT ON COLUMN "parties"."disbanded_at" IS 'When the group broke up. Rows are kept so a match roster can still explain who queued with whom.';

CREATE INDEX "idx_parties_leader"
ON "parties" ("leader_player_id");
CREATE INDEX "idx_parties_state_region"
ON "parties" ("state", "region_code");

CREATE TABLE IF NOT EXISTS "party_members" (
	-- Group being joined. Half of the composite primary key.
	"party_id" BIGINT,
	-- Member. Half of the composite key, which also enforces that a player is in at most one party at a time.
	"player_id" BIGINT,
	-- Lobby ready check. Every member must be ready before a ticket may be created.
	"is_ready" BOOLEAN NOT NULL DEFAULT false,
	-- When they joined. Ordering members by this gives a stable lobby list.
	"joined_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("party_id", "player_id")
);

COMMENT ON TABLE "party_members" IS 'Party membership. The composite primary key carries no surrogate id because the pair is the identity, and it is the constraint that stops a player being matched into two matches at once.';
COMMENT ON COLUMN "party_members"."party_id" IS 'Group being joined. Half of the composite primary key.';
COMMENT ON COLUMN "party_members"."player_id" IS 'Member. Half of the composite key, which also enforces that a player is in at most one party at a time.';
COMMENT ON COLUMN "party_members"."is_ready" IS 'Lobby ready check. Every member must be ready before a ticket may be created.';
COMMENT ON COLUMN "party_members"."joined_at" IS 'When they joined. Ordering members by this gives a stable lobby list.';

CREATE TABLE IF NOT EXISTS "queue_tickets" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Group searching. Always present because a solo player is a party of one.
	"party_id" BIGINT NOT NULL,
	-- Mode being searched. With region_code this pair is the queue.
	"playlist_id" BIGINT NOT NULL,
	-- Datacentre region the search targets. The second half of the queue identity, so a playlist has as many live queues as it has regions.
	"region_code" VARCHAR(12) NOT NULL,
	-- Members at enqueue time. Denormalised so the matchmaker can bin-pack rosters without joining party_members.
	"party_size" SMALLINT NOT NULL,
	-- Skill the ticket searches around, usually the party average weighted toward its highest member.
	"search_mu" NUMERIC(8,3) NOT NULL,
	-- Half-width of the acceptable skill band. It widens on a timer, which is the explicit trade of match quality for wait time.
	"search_radius" NUMERIC(8,3) NOT NULL,
	-- searching | proposed | matched | cancelled | expired. A ticket in proposed is held out of the pool until the accept window closes.
	"state" VARCHAR(16) NOT NULL DEFAULT 'searching',
	-- When the search started. Wait time and radius widening are both measured from here.
	"enqueued_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Last radius expansion. Null until the first widening.
	"last_widened_at" TIMESTAMPTZ,
	-- Last state transition, used to expire tickets whose client stopped heartbeating.
	"state_changed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "queue_tickets" IS 'One live search. The ticket, not the party, is the unit the matchmaker scans, because a group can cancel and requeue with different parameters and each attempt needs its own wait clock.';
COMMENT ON COLUMN "queue_tickets"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "queue_tickets"."party_id" IS 'Group searching. Always present because a solo player is a party of one.';
COMMENT ON COLUMN "queue_tickets"."playlist_id" IS 'Mode being searched. With region_code this pair is the queue.';
COMMENT ON COLUMN "queue_tickets"."region_code" IS 'Datacentre region the search targets. The second half of the queue identity, so a playlist has as many live queues as it has regions.';
COMMENT ON COLUMN "queue_tickets"."party_size" IS 'Members at enqueue time. Denormalised so the matchmaker can bin-pack rosters without joining party_members.';
COMMENT ON COLUMN "queue_tickets"."search_mu" IS 'Skill the ticket searches around, usually the party average weighted toward its highest member.';
COMMENT ON COLUMN "queue_tickets"."search_radius" IS 'Half-width of the acceptable skill band. It widens on a timer, which is the explicit trade of match quality for wait time.';
COMMENT ON COLUMN "queue_tickets"."state" IS 'searching | proposed | matched | cancelled | expired. A ticket in proposed is held out of the pool until the accept window closes.';
COMMENT ON COLUMN "queue_tickets"."enqueued_at" IS 'When the search started. Wait time and radius widening are both measured from here.';
COMMENT ON COLUMN "queue_tickets"."last_widened_at" IS 'Last radius expansion. Null until the first widening.';
COMMENT ON COLUMN "queue_tickets"."state_changed_at" IS 'Last state transition, used to expire tickets whose client stopped heartbeating.';

CREATE INDEX "idx_tickets_queue_search"
ON "queue_tickets" ("playlist_id", "region_code", "state", "search_mu");
CREATE INDEX "idx_tickets_party_state"
ON "queue_tickets" ("party_id", "state");

CREATE TABLE IF NOT EXISTS "game_servers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Datacentre region. A match can only be assigned a server in the region its tickets searched.
	"region_code" VARCHAR(12) NOT NULL,
	-- Where the machine came from, e.g. a cloud region or a bare-metal pool. Matters when one provider degrades.
	"provider" VARCHAR(40) NOT NULL,
	-- Address the client connects to.
	"host" VARCHAR(255) NOT NULL,
	-- Port for this instance. A host runs many instances, so host alone is not the identity.
	"port" INTEGER NOT NULL,
	-- Game build the process is running. Clients on a different build cannot be placed here, which is the main cause of capacity looking free but being unusable.
	"build_version" VARCHAR(40) NOT NULL,
	-- Concurrent matches this instance can host.
	"capacity" SMALLINT NOT NULL DEFAULT 1,
	-- Matches currently running on it. Allocation requires active_matches below capacity, checked in the same transaction that assigns the match.
	"active_matches" SMALLINT NOT NULL DEFAULT 0,
	-- available | draining | offline. Draining keeps live matches but accepts no new ones, which is how a deploy happens without kicking anyone.
	"state" VARCHAR(16) NOT NULL DEFAULT 'available',
	-- Last check-in. A stale heartbeat marks the server offline and its live matches as candidates for abandonment handling.
	"heartbeat_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "game_servers" IS 'A process that can host matches. Capacity is a counter rather than a computed count so allocation is one conditional update instead of a scan of live matches.';
COMMENT ON COLUMN "game_servers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "game_servers"."region_code" IS 'Datacentre region. A match can only be assigned a server in the region its tickets searched.';
COMMENT ON COLUMN "game_servers"."provider" IS 'Where the machine came from, e.g. a cloud region or a bare-metal pool. Matters when one provider degrades.';
COMMENT ON COLUMN "game_servers"."host" IS 'Address the client connects to.';
COMMENT ON COLUMN "game_servers"."port" IS 'Port for this instance. A host runs many instances, so host alone is not the identity.';
COMMENT ON COLUMN "game_servers"."build_version" IS 'Game build the process is running. Clients on a different build cannot be placed here, which is the main cause of capacity looking free but being unusable.';
COMMENT ON COLUMN "game_servers"."capacity" IS 'Concurrent matches this instance can host.';
COMMENT ON COLUMN "game_servers"."active_matches" IS 'Matches currently running on it. Allocation requires active_matches below capacity, checked in the same transaction that assigns the match.';
COMMENT ON COLUMN "game_servers"."state" IS 'available | draining | offline. Draining keeps live matches but accepts no new ones, which is how a deploy happens without kicking anyone.';
COMMENT ON COLUMN "game_servers"."heartbeat_at" IS 'Last check-in. A stale heartbeat marks the server offline and its live matches as candidates for abandonment handling.';

CREATE INDEX "idx_servers_region_state_build"
ON "game_servers" ("region_code", "state", "build_version");

CREATE TABLE IF NOT EXISTS "match_proposals" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Playlist the proposed match belongs to.
	"playlist_id" BIGINT NOT NULL,
	-- Region the roster was assembled in.
	"region_code" VARCHAR(12) NOT NULL,
	-- Server reserved for the match. Null when allocation is deferred until everyone accepts, which is the cheaper policy.
	"server_id" BIGINT,
	-- pending | accepted | declined | expired | cancelled. Only accepted proposals produce a match.
	"state" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- How many players must accept. Snapshotted from the roster size so a later playlist change cannot retroactively alter the bar.
	"required_accepts" SMALLINT NOT NULL,
	-- Accepts received so far. Denormalised so the ready-check UI is one read.
	"accept_count" SMALLINT NOT NULL DEFAULT 0,
	-- Predicted balance of the proposed teams, zero to one. Kept so declined proposals can be mined for what players actually reject.
	"quality_score" NUMERIC(5,4),
	-- Hard deadline for the accept window. On expiry every non-responder is marked timed_out and the accepting tickets go back to searching with their wait clock preserved.
	"expires_at" TIMESTAMPTZ NOT NULL,
	-- When the roster was formed.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "match_proposals" IS 'A candidate match waiting on acceptance. It is a separate table from matches because most proposals never become one, and the rate at which they fail is the single most useful health metric a matchmaker has.';
COMMENT ON COLUMN "match_proposals"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "match_proposals"."playlist_id" IS 'Playlist the proposed match belongs to.';
COMMENT ON COLUMN "match_proposals"."region_code" IS 'Region the roster was assembled in.';
COMMENT ON COLUMN "match_proposals"."server_id" IS 'Server reserved for the match. Null when allocation is deferred until everyone accepts, which is the cheaper policy.';
COMMENT ON COLUMN "match_proposals"."state" IS 'pending | accepted | declined | expired | cancelled. Only accepted proposals produce a match.';
COMMENT ON COLUMN "match_proposals"."required_accepts" IS 'How many players must accept. Snapshotted from the roster size so a later playlist change cannot retroactively alter the bar.';
COMMENT ON COLUMN "match_proposals"."accept_count" IS 'Accepts received so far. Denormalised so the ready-check UI is one read.';
COMMENT ON COLUMN "match_proposals"."quality_score" IS 'Predicted balance of the proposed teams, zero to one. Kept so declined proposals can be mined for what players actually reject.';
COMMENT ON COLUMN "match_proposals"."expires_at" IS 'Hard deadline for the accept window. On expiry every non-responder is marked timed_out and the accepting tickets go back to searching with their wait clock preserved.';
COMMENT ON COLUMN "match_proposals"."created_at" IS 'When the roster was formed.';

CREATE INDEX "idx_proposals_state_expiry"
ON "match_proposals" ("state", "expires_at");
CREATE INDEX "idx_proposals_queue_time"
ON "match_proposals" ("playlist_id", "region_code", "created_at");

CREATE TABLE IF NOT EXISTS "proposal_responses" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Proposal being answered.
	"proposal_id" BIGINT NOT NULL,
	-- Ticket the player was pulled from. Needed to return the whole party to the queue together when someone else declines.
	"ticket_id" BIGINT NOT NULL,
	-- Player answering.
	"player_id" BIGINT NOT NULL,
	-- Team the player was assigned to in this proposal. Kept here so a re-proposal can avoid recreating the same disliked composition.
	"team_index" SMALLINT NOT NULL,
	-- pending | accepted | declined | timed_out. Declined and timed_out are separated on purpose - one is a choice and only one of them should carry a penalty.
	"response" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- When they answered. Null while pending; the gap to the proposal deadline is what distinguishes an away-from-keyboard player from a deliberate decline.
	"responded_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "proposal_responses" IS 'One row per player per proposal. This table is where decline rates, dodge patterns and away-from-keyboard detection all come from, which is why responses are kept after the proposal dies.';
COMMENT ON COLUMN "proposal_responses"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "proposal_responses"."proposal_id" IS 'Proposal being answered.';
COMMENT ON COLUMN "proposal_responses"."ticket_id" IS 'Ticket the player was pulled from. Needed to return the whole party to the queue together when someone else declines.';
COMMENT ON COLUMN "proposal_responses"."player_id" IS 'Player answering.';
COMMENT ON COLUMN "proposal_responses"."team_index" IS 'Team the player was assigned to in this proposal. Kept here so a re-proposal can avoid recreating the same disliked composition.';
COMMENT ON COLUMN "proposal_responses"."response" IS 'pending | accepted | declined | timed_out. Declined and timed_out are separated on purpose - one is a choice and only one of them should carry a penalty.';
COMMENT ON COLUMN "proposal_responses"."responded_at" IS 'When they answered. Null while pending; the gap to the proposal deadline is what distinguishes an away-from-keyboard player from a deliberate decline.';

CREATE UNIQUE INDEX "uq_responses_proposal_player"
ON "proposal_responses" ("proposal_id", "player_id");
CREATE INDEX "idx_responses_player_time"
ON "proposal_responses" ("player_id", "responded_at");

CREATE TABLE IF NOT EXISTS "matches" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Proposal that produced it. Unique, and null for matches created outside the queue such as a custom or tournament game.
	"proposal_id" BIGINT UNIQUE,
	-- Playlist played.
	"playlist_id" BIGINT NOT NULL,
	-- Region the match ran in. Kept on the match because the server row can be recycled or deleted.
	"region_code" VARCHAR(12) NOT NULL,
	-- Server that hosted it. Nullable so retiring a machine does not erase match history.
	"server_id" BIGINT,
	-- provisioning | live | completed | abandoned | cancelled. Only completed matches feed rating updates.
	"state" VARCHAR(20) NOT NULL DEFAULT 'provisioning',
	-- Snapshotted from the playlist. A mid-season change to the playlist must not retroactively make old matches ranked.
	"is_ranked" BOOLEAN NOT NULL DEFAULT true,
	-- Whether the matchmaker may place new players into empty slots. Closes after a threshold of elapsed time, past which joining is worse than playing short.
	"backfill_open" BOOLEAN NOT NULL DEFAULT false,
	-- Team that won. Null for a draw, and null while the match is live.
	"winning_team_index" SMALLINT,
	-- When play actually began, which is later than creation by the load time of the slowest client.
	"started_at" TIMESTAMPTZ,
	-- When the result was reported. Null until then.
	"ended_at" TIMESTAMPTZ,
	-- Row creation, at allocation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "matches" IS 'A match that was actually created. Team results live on the slots rather than in a teams table, because with winning_team_index plus per-slot placement there is nothing a separate team row would add.';
COMMENT ON COLUMN "matches"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "matches"."proposal_id" IS 'Proposal that produced it. Unique, and null for matches created outside the queue such as a custom or tournament game.';
COMMENT ON COLUMN "matches"."playlist_id" IS 'Playlist played.';
COMMENT ON COLUMN "matches"."region_code" IS 'Region the match ran in. Kept on the match because the server row can be recycled or deleted.';
COMMENT ON COLUMN "matches"."server_id" IS 'Server that hosted it. Nullable so retiring a machine does not erase match history.';
COMMENT ON COLUMN "matches"."state" IS 'provisioning | live | completed | abandoned | cancelled. Only completed matches feed rating updates.';
COMMENT ON COLUMN "matches"."is_ranked" IS 'Snapshotted from the playlist. A mid-season change to the playlist must not retroactively make old matches ranked.';
COMMENT ON COLUMN "matches"."backfill_open" IS 'Whether the matchmaker may place new players into empty slots. Closes after a threshold of elapsed time, past which joining is worse than playing short.';
COMMENT ON COLUMN "matches"."winning_team_index" IS 'Team that won. Null for a draw, and null while the match is live.';
COMMENT ON COLUMN "matches"."started_at" IS 'When play actually began, which is later than creation by the load time of the slowest client.';
COMMENT ON COLUMN "matches"."ended_at" IS 'When the result was reported. Null until then.';
COMMENT ON COLUMN "matches"."created_at" IS 'Row creation, at allocation time.';

CREATE INDEX "idx_matches_state_created"
ON "matches" ("state", "created_at");
CREATE INDEX "idx_matches_playlist_ended"
ON "matches" ("playlist_id", "ended_at");

CREATE TABLE IF NOT EXISTS "match_slots" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Match the slot belongs to.
	"match_id" BIGINT NOT NULL,
	-- Zero-based team number. Every slot in a match exists from creation, filled or not.
	"team_index" SMALLINT NOT NULL,
	-- Position within the team. The pair with team_index is the roster coordinate a backfill request quotes.
	"slot_index" SMALLINT NOT NULL,
	-- Occupant. Null means the slot is empty and eligible for backfill, which is exactly what a mid-match leave produces.
	"player_id" BIGINT,
	-- Party the player queued with. Kept so premade-versus-solo balance can be measured after the fact.
	"party_id" BIGINT,
	-- Ticket that filled the slot. Null for a backfill placement, which bypasses the normal search.
	"ticket_id" BIGINT,
	-- True when the player joined a match already in progress. Backfilled players are usually excluded from rating loss.
	"is_backfill" BOOLEAN NOT NULL DEFAULT false,
	-- Rating snapshot at placement. Frozen so the update computes against what the system believed then, not what it believes when the result is reported.
	"rating_mu_at_start" NUMERIC(8,3),
	-- When the client connected. Null while the slot is unfilled.
	"joined_at" TIMESTAMPTZ,
	-- When the client disconnected. A value before the match ended is what abandonment detection keys on.
	"left_at" TIMESTAMPTZ,
	-- Set when the leave was judged an abandonment rather than a crash or a server fault. Only this flag, never left_at alone, triggers a penalty.
	"abandoned" BOOLEAN NOT NULL DEFAULT false,
	-- Finish position for modes without a single winning team, such as battle royale. Null for team modes.
	"placement" SMALLINT,
	-- Reported performance number. Kept for review and for performance-weighted rating experiments.
	"score" INTEGER,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "match_slots" IS 'One roster position. Creating every slot up front, filled or empty, is what makes backfill a simple UPDATE of a null player_id rather than a second concept bolted onto the match.';
COMMENT ON COLUMN "match_slots"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "match_slots"."match_id" IS 'Match the slot belongs to.';
COMMENT ON COLUMN "match_slots"."team_index" IS 'Zero-based team number. Every slot in a match exists from creation, filled or not.';
COMMENT ON COLUMN "match_slots"."slot_index" IS 'Position within the team. The pair with team_index is the roster coordinate a backfill request quotes.';
COMMENT ON COLUMN "match_slots"."player_id" IS 'Occupant. Null means the slot is empty and eligible for backfill, which is exactly what a mid-match leave produces.';
COMMENT ON COLUMN "match_slots"."party_id" IS 'Party the player queued with. Kept so premade-versus-solo balance can be measured after the fact.';
COMMENT ON COLUMN "match_slots"."ticket_id" IS 'Ticket that filled the slot. Null for a backfill placement, which bypasses the normal search.';
COMMENT ON COLUMN "match_slots"."is_backfill" IS 'True when the player joined a match already in progress. Backfilled players are usually excluded from rating loss.';
COMMENT ON COLUMN "match_slots"."rating_mu_at_start" IS 'Rating snapshot at placement. Frozen so the update computes against what the system believed then, not what it believes when the result is reported.';
COMMENT ON COLUMN "match_slots"."joined_at" IS 'When the client connected. Null while the slot is unfilled.';
COMMENT ON COLUMN "match_slots"."left_at" IS 'When the client disconnected. A value before the match ended is what abandonment detection keys on.';
COMMENT ON COLUMN "match_slots"."abandoned" IS 'Set when the leave was judged an abandonment rather than a crash or a server fault. Only this flag, never left_at alone, triggers a penalty.';
COMMENT ON COLUMN "match_slots"."placement" IS 'Finish position for modes without a single winning team, such as battle royale. Null for team modes.';
COMMENT ON COLUMN "match_slots"."score" IS 'Reported performance number. Kept for review and for performance-weighted rating experiments.';

CREATE UNIQUE INDEX "uq_slots_match_team_slot"
ON "match_slots" ("match_id", "team_index", "slot_index");
CREATE INDEX "idx_slots_player_time"
ON "match_slots" ("player_id", "joined_at");

CREATE TABLE IF NOT EXISTS "player_penalties" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Player being restricted.
	"player_id" BIGINT NOT NULL,
	-- Playlist the ban applies to. Null means every ranked playlist, which is the usual scope for a repeat abandoner.
	"playlist_id" BIGINT,
	-- Match that triggered it. Null for penalties from a proposal decline or a manual action.
	"match_id" BIGINT,
	-- abandon | decline | idle | report | manual. Decline and abandon are counted separately because their tolerable rates differ by an order of magnitude.
	"reason" VARCHAR(24) NOT NULL,
	-- Offence number within the rolling window. Duration escalates with this, which is why the level is stored rather than derived at read time from a history that may have been pruned.
	"severity_level" SMALLINT NOT NULL DEFAULT 1,
	-- When the restriction begins.
	"starts_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When it lifts. Enqueue checks for any row where now lies between starts_at and ends_at and waived_at is null.
	"ends_at" TIMESTAMPTZ NOT NULL,
	-- Set when support reverses it. The row stays so the escalation ladder still remembers the offence happened.
	"waived_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "player_penalties" IS 'Temporary queue restrictions. Penalties are rows with a window rather than a flag on the player, so they expire without a job, stack correctly, and leave an auditable record when appealed.';
COMMENT ON COLUMN "player_penalties"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "player_penalties"."player_id" IS 'Player being restricted.';
COMMENT ON COLUMN "player_penalties"."playlist_id" IS 'Playlist the ban applies to. Null means every ranked playlist, which is the usual scope for a repeat abandoner.';
COMMENT ON COLUMN "player_penalties"."match_id" IS 'Match that triggered it. Null for penalties from a proposal decline or a manual action.';
COMMENT ON COLUMN "player_penalties"."reason" IS 'abandon | decline | idle | report | manual. Decline and abandon are counted separately because their tolerable rates differ by an order of magnitude.';
COMMENT ON COLUMN "player_penalties"."severity_level" IS 'Offence number within the rolling window. Duration escalates with this, which is why the level is stored rather than derived at read time from a history that may have been pruned.';
COMMENT ON COLUMN "player_penalties"."starts_at" IS 'When the restriction begins.';
COMMENT ON COLUMN "player_penalties"."ends_at" IS 'When it lifts. Enqueue checks for any row where now lies between starts_at and ends_at and waived_at is null.';
COMMENT ON COLUMN "player_penalties"."waived_at" IS 'Set when support reverses it. The row stays so the escalation ladder still remembers the offence happened.';

CREATE INDEX "idx_penalties_player_active"
ON "player_penalties" ("player_id", "ends_at");
CREATE INDEX "idx_penalties_reason_time"
ON "player_penalties" ("reason", "starts_at");

